<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const items=ref<any[]>([]),unread=ref(0),rules=ref<any[]>([]);async function load(){const[n,r]=await Promise.all([api.get('/notifications',{params:{page:1,page_size:100}}),api.get('/reminder-rules').catch(()=>({data:{items:[]}}))]);items.value=n.data.items||[];unread.value=n.data.unread||0;rules.value=r.data.items||[]}async function read(id:string){await api.post(`/notifications/${id}/read`);await load()}async function readAll(){await api.post('/notifications/read-all');await load()}async function run(){await api.post('/reminders/run');await load()}onMounted(load)</script>
<template><div class="page"><div class="page-title"><div><h1>通知提醒</h1><p>集中查看租约到期、逾期账单和维修超时提醒</p></div><div class="action-group"><button class="secondary-button" @click="run">立即生成提醒</button><button class="primary-button" @click="readAll">全部已读</button></div></div><div class="stat-grid"><div class="stat-card"><span>未读消息</span><strong>{{unread}}</strong></div><div class="stat-card"><span>提醒规则</span><strong>{{rules.filter(x=>x.Enabled).length}}</strong></div><div class="stat-card"><span>全部消息</span><strong>{{items.length}}</strong></div></div><section class="card"><div v-for="x in items" :key="x.ID" class="notice-row"><div><strong>{{x.Title}}</strong><p>{{x.Content}}</p><span>{{x.Category}} · {{x.CreatedAt}}</span></div><button v-if="x.Status==='unread'" class="secondary-button" @click="read(x.ID)">标记已读</button></div><div v-if="!items.length" class="empty-state"><b>暂无通知</b><span>系统将按提醒规则自动生成消息</span></div></section></div></template>
